CREATE TABLE customer_visit_days(customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE,day TEXT NOT NULL,PRIMARY KEY(customer_id,day));
INSERT OR IGNORE INTO customer_visit_days SELECT customer_id,date(COALESCE(delivered_at,created_at)+10800,'unixepoch') FROM orders WHERE customer_id IS NOT NULL AND status='delivered';
CREATE TRIGGER royal_visit_day AFTER UPDATE OF status ON orders WHEN NEW.status='delivered' AND OLD.status!='delivered' AND NEW.customer_id IS NOT NULL BEGIN INSERT OR IGNORE INTO customer_visit_days VALUES(NEW.customer_id,date(COALESCE(NEW.delivered_at,CAST(strftime('%s','now') AS INTEGER))+10800,'unixepoch')); END;
CREATE TABLE customer_quizzes(customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE,day TEXT NOT NULL,question_key TEXT NOT NULL,answer INTEGER NOT NULL,correct INTEGER NOT NULL,PRIMARY KEY(customer_id,day));
CREATE TABLE customer_recipes(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE,product_id TEXT NOT NULL REFERENCES products(id),name TEXT NOT NULL,notes TEXT NOT NULL,options TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TRIGGER royal_recipe_quota BEFORE INSERT ON customer_recipes WHEN NOT EXISTS(SELECT 1 FROM customer_recipes WHERE id=NEW.id) AND (SELECT COUNT(*) FROM customer_recipes WHERE customer_id=NEW.customer_id)>=20 BEGIN SELECT RAISE(ABORT,'recipe_quota'); END;
